import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {calendarWeek,forecastForWeek,clampWindowPosition,forecastWindowLayout} from '../.test-build/forecastModel.mjs';

// Generated by the unchanged Python scheduler immediately before this test run.
const demo=JSON.parse(readFileSync(new URL('../.test-build/demo.json',import.meta.url),'utf8'));
const source=demo.schedule.crop_forecasts;

test('ISO weeks include Monday and Sunday, exclude following Monday',()=>{
  assert.deepEqual(calendarWeek('2026-06-15'),calendarWeek('2026-06-21'));
  assert.equal(calendarWeek('2026-06-21').number,25);
  assert.equal(calendarWeek('2026-06-22').start,'2026-06-22');
  assert.equal(calendarWeek('2026-06-21').endExclusive,'2026-06-22');
});

test('ISO week-year and DST boundaries use calendar dates',()=>{
  const week=calendarWeek('2021-01-03');
  assert.equal(week.year,2020);assert.equal(week.number,53);assert.equal(week.start,'2020-12-28');
  assert.equal(calendarWeek('2021-01-04').number,1);
  assert.equal(calendarWeek('2026-03-29').start,'2026-03-23');
});

test('Real scheduler harvest remains visible after all beds have become free',()=>{
  const day=demo.days.find(d=>d.date==='2026-06-20');
  assert.ok(Object.values(day.beds).every(b=>b.stage==='free'));
  const result=forecastForWeek(source,day.date);
  assert.deepEqual(result.rows,[{crop_id:'lettuce',unit:'pieces',quantity:600}]);
  assert.deepEqual(result.rows,forecastForWeek(source,'2026-06-15').rows);
  assert.deepEqual(result.rows,forecastForWeek(source,'2026-06-21').rows);
  assert.deepEqual(forecastForWeek(source,'2026-06-22').rows,[]);
});

test('Empty weeks do not include other weeks or annual totals',()=>{
  assert.deepEqual(forecastForWeek(source,'2026-06-10').rows,[]);
  const weekly=forecastForWeek(source,'2026-08-16').rows;
  assert.deepEqual(weekly,[{crop_id:'tomatoes',unit:'kg',quantity:24.25}]);
  const annual=source.filter(r=>r.crop_id==='tomatoes').reduce((sum,r)=>sum+r.quantity,0);
  assert.notEqual(weekly[0].quantity,annual);
});

test('Use complete weekly harvest, including uncredited multicut yield',()=>{
  const original=source.find(r=>r.crop_id==='spinach'&&r.week_start==='2026-10-26');
  assert.equal(original.credited_quantity,0);
  assert.equal(original.quantity,36);
  assert.deepEqual(forecastForWeek(source,'2026-10-31').rows,[{crop_id:'spinach',unit:'kg',quantity:36}]);
});

test('Group culture and unit separately; skip zero rows and other weeks',()=>{
  // Synthetic contract fixtures only; never part of production UI data.
  const row=(crop_id,unit,quantity,week_start='2026-06-15')=>({crop_id,unit,quantity,credited_quantity:0,week_start});
  const result=forecastForWeek([row('a','kg',2),row('a','kg',3),row('a','pieces',7),row('b','kg',0),row('a','kg',99,'2026-06-22')],'2026-06-20');
  assert.deepEqual(result.rows,[{crop_id:'a',unit:'kg',quantity:5},{crop_id:'a',unit:'pieces',quantity:7}]);
});

test('Window position is bounded after arbitrary drags and viewport resize',()=>{
  for(const viewport of [{width:987,height:830},{width:390,height:844},{width:320,height:650}]) {
    const layout=forecastWindowLayout(viewport),size={width:layout.width,height:layout.maxHeight};
    for(const point of [{x:-1000,y:-1000},{x:2000,y:2000},{x:800,y:600},layout.initial]) {
      const p=clampWindowPosition(point,size,viewport);
      assert.ok(p.x>=12&&p.y>=12);
      assert.ok(p.x+size.width<=viewport.width-12);
      assert.ok(p.y+size.height<=viewport.height-12);
    }
  }
});

test('Initial desktop placement leaves title, expanded legend, season and details available',()=>{
  const layout=forecastWindowLayout({width:987,height:830});
  assert.ok(layout.initial.y>=325); // Expanded legend ends here.
  assert.ok(layout.initial.x+layout.width<665); // Right detail panel starts here.
  assert.ok(layout.initial.y+layout.maxHeight<693); // Bottom season bar starts here.
  const mobile=forecastWindowLayout({width:390,height:844});
  assert.ok(mobile.initial.y>=475);
  assert.ok(mobile.initial.y+mobile.maxHeight<=701);
});
